"""mpl_toolkits.axisartist — custom axis artist toolkit."""

from mpl_toolkits.axisartist.axislines import Axes, SubplotZero, Subplot
from mpl_toolkits.axisartist.axis_artist import AxisArtist
from mpl_toolkits.axisartist.grid_finder import GridFinder

# Upstream aliases ``AxesZero`` to the same class as ``SubplotZero``
# (both render the x/y axes through the origin).
AxesZero = SubplotZero

__all__ = ['Axes', 'AxesZero', 'SubplotZero', 'Subplot', 'AxisArtist',
           'GridFinder']


# ─── Added: missing public classes ──────────────────────────────────


from mpl_toolkits.axisartist.parasite_axes import SubplotHost
from mpl_toolkits.axes_grid1.parasite_axes import parasite_axes_class_factory as _factory

# Host/Parasite axes — re-exported aliases for the axes-classes the
# parasite_axes module synthesises.
from matplotlib.axes._axes import Axes as _BaseAxes


class HostAxes(_BaseAxes):
    """Axes that can host parasites — mirrors upstream's class."""
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._parasites = []
    def get_aux_axes(self, tr=None, viewlim_mode='equal', axes_class=None):
        Cls = _factory(axes_class)
        p = Cls(self); self._parasites.append(p); return p


class ParasiteAxes(_BaseAxes):
    """Axes drawn on top of a :class:`HostAxes`."""
    def __init__(self, host, *args, **kwargs):
        super().__init__(host.figure if hasattr(host, 'figure') else None,
                          *args, **kwargs)
        self._host = host


__all__ += ['HostAxes', 'ParasiteAxes', 'SubplotHost']
